INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_ar_jan_q2', 'exam_primary_2023_didactics_ar_jan', 2, 'الكتابة — مكونات الكتابة', 'عناصر مكون الكتابة في السنة الثانية هي:', false, '[{"id": "A", "text": "خط - نقل - تمارين كتابية - تعبير كتابي."}, {"id": "B", "text": "خط - نقل - تطبيقات كتابية - تعبير كتابي."}, {"id": "C", "text": "خط - إملاء - تمارين كتابية - تعبير كتابي."}, {"id": "D", "text": "خط - إملاء - تطبيقات كتابية - تعبير كتابي."}]'::jsonb, ARRAY['D']::text[], 'خط، إملاء، تطبيقات كتابية، تعبير كتابي. حسب المنهاج الدراسي المنقح للغة العربية بالتعليم الابتدائي (2021) ودليل الأستاذ، يظهر الإملاء ابتداء من السنة الثانية إلى جانب الخط والتطبيقات الكتابية والتعبير الكتابي.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42527-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان. تعارض منشور: wadifa-info يقترح C (خط، إملاء، تمارين كتابية، تعبير كتابي)، مستنداً إلى جدول المكونات الدراسية (ص. 72): الكتابة في السنة الثانية = الخط؛ الإملاء – تمارين كتابية؛ التعبير الكتابي، ويقول إن «التطبيقات الكتابية» تبدأ في السنة الثالثة. الجواب المعتمد هنا هو جواب manasseb (D).')
