INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_ar_jan_q16', 'exam_primary_2023_didactics_ar_jan', 16, 'القراءة — نصوص القراءة المشتركة', 'من معايير نصوص القراءة المشتركة في السنة الثانية أنها:', false, '[{"id": "A", "text": "مرتبطة بمجال الوحدة الدراسية، قصيرة، مناسبة لاهتمامات الأطفال، ذات إيقاعات خفيفة."}, {"id": "B", "text": "مرتبطة بمجال الوحدة الدراسية، قصيرة، ذات إيقاعات خفيفة، ذات جمل بسيطة، مسترسلة."}, {"id": "C", "text": "مرتبطة بمجال الوحدة الدراسية، قصيرة، مناسبة لاهتمامات الأطفال، شعرية."}, {"id": "D", "text": "مرتبطة بمجال الوحدة الدراسية، وظيفية، ذات جمل بسيطة، مناسبة لاهتمامات الأطفال."}]'::jsonb, ARRAY['A']::text[], 'معايير إعداد نصوص القراءة المشتركة: «مرتبطة بمجال الوحدة الدراسية؛ قصيرة (12 إلى 25 كلمة في السنة الثانية)؛ مركبة من كلمات وجمل بسيطة بلغة سليمة وإيقاعات خفيفة؛ مناسبة لاهتمامات الأطفال» (ص. 96). يسقط B بكلمة «مسترسلة»، وC بكلمة «شعرية»، وD بكلمة «وظيفية».', 'qcm', 'third_party', 'https://www.wadifa-info.com/fr/modele-concours/2195/modele-de-concours-professeurs-de-l-enseignement-primaire-2e-grade-crmef-specialite-doub', true, 'manasseb لم يقترح جوابا؛ الجواب من wadifa-info.')
