INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_ar_jan_q21', 'exam_primary_2023_didactics_ar_jan', 21, 'البرنامج الدراسي — السنتان الخامسة والسادسة', 'يغلب على البرنامج الدراسي لمادة اللغة العربية في السنتين الخامسة والسادسة:', false, '[{"id": "A", "text": "طابع البناء والتثبيت والتركيز والتوسع التدريجي."}, {"id": "B", "text": "طابع التوسع التدريجي الأفقي للمكتسبات اللغوية."}, {"id": "C", "text": "طابع الترسيخ والتعميق العمودي وترصيد المكتسبات."}, {"id": "D", "text": "طابع التحسيس والترسيخ والتوسع التدريجي."}]'::jsonb, ARRAY['C']::text[], 'الترسيخ والتعميق وترصيد المكتسبات في نهاية السلك. السنتان الخامسة والسادسة نهاية السلك، والمنهاج يربطهما بالترسيخ والتعميق وترصيد المكتسبات.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42527-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان.')
