-- أسئلة امتحان: ديداكتيك اللغة العربية — Q22
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_ar_jan_q22', 'exam_primary_2023_didactics_ar_jan', 22, 'الأسس النظرية لبناء التعلمات', 'من بين أهم الأسس النظرية لبناء التعلمات:', false, '[{"id": "A", "text": "النظرية البنائية الجديدة، نموذج فيجوتسكي، نظرية النماذج، النظرية البنائية."}, {"id": "B", "text": "النظرية البنائية الجديدة، نموذج فيجوتسكي، نظرية التلقي، النظرية البنائية."}, {"id": "C", "text": "النظرية البنيوية، نموذج فيجوتسكي، النظرية البنائية، نظرية النماذج."}, {"id": "D", "text": "النظرية البنيوية، نموذج فيجوتسكي، النظرية البنائية الجديدة، نظرية النماذج."}]'::jsonb, ARRAY['A']::text[], 'لا يعرض المنهاج الدراسي لسنة 2021 لائحة «الأسس النظرية لبناء التعلمات» بهذه الصيغة، فالجواب مبني على المعرفة البيداغوجية العامة: الاختيار A هو الوحيد الذي تتكون عناصره الأربعة كلها من نظريات تعلّم (البنائية، البنائية الجديدة/الاجتماعية، نموذج فيجوتسكي، التعلم بالنماذج أو النمذجة، وهي خطوة يعتمدها المنهاج نفسه في التفويض التدريجي للمسؤولية، ص. 59 و86). أما الاختياران C وD فيُدخلان البنيوية، وهي نظرية لسانية في وصف اللغة لا نظرية في بناء التعلمات، والاختيار B يُدخل نظرية التلقي، وهي نظرية أدبية في القراءة والتأويل.', 'qcm', 'third_party', 'https://www.wadifa-info.com/fr/modele-concours/2195/modele-de-concours-professeurs-de-l-enseignement-primaire-2e-grade-crmef-specialite-doub', true, 'manasseb لم يقترح جوابا؛ الجواب من wadifa-info. إجابة مرجّحة حسب wadifa-info؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان.')
