-- أسئلة امتحان: ديداكتيك اللغة العربية — Q23
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_ar_jan_q23', 'exam_primary_2023_didactics_ar_jan', 23, 'الإملاء — تدبير الحصص', 'في السنة السادسة، تخصص حصتا الأسبوعين الثالث والرابع من الوحدة الدراسية في مكون الإملاء لـ:', false, '[{"id": "A", "text": "تقديم الظاهرة الإملائية فقط."}, {"id": "B", "text": "إنجاز تطبيقات على الظاهرة الإملائية وتصفية الصعوبات."}, {"id": "C", "text": "تقديم الظاهرة الإملائية وتصفية الصعوبات."}, {"id": "D", "text": "تصفية الصعوبات الإملائية فقط."}]'::jsonb, ARRAY['B']::text[], 'إنجاز تطبيقات على الظاهرة الإملائية وتصفية الصعوبات. في وحدة من أربعة أسابيع، يخصص الأسبوعان الأولان لتقديم الظاهرة والأسبوعان الأخيران للتطبيقات وتصفية الصعوبات.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42527-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان. تعارض منشور: wadifa-info يقترح D (تصفية الصعوبات الإملائية فقط)، مستنداً إلى المنهاج (ص. 125): «تقدم الظاهرة الإملائية في السنة السادسة في حصتين خلال الأسبوعين الأول والثاني، وتخصص حصتا الأسبوعين الثالث والرابع لتصفية الصعوبات الإملائية التي يتم رصدها في إنتاجات المتعلمات والمتعلمين». وسؤال الامتحان نفسه يسأل عن حصتي الأسبوعين الثالث والرابع تحديداً. الجواب المعتمد هنا هو جواب manasseb (B).')
