VALUES ('exam_primary_2023_didactics_ar_jan_q24', 'exam_primary_2023_didactics_ar_jan', 24, 'الكتابة — تدبير الحصص', 'في الأنشطة الكتابية للسنة الأولى، يقدم حرفان في الأسبوع خلال الوحدتين:', false, '[{"id": "A", "text": "الأولى والثانية."}, {"id": "B", "text": "الثانية والثالثة."}, {"id": "C", "text": "الثالثة والرابعة."}, {"id": "D", "text": "الرابعة والخامسة."}]'::jsonb, ARRAY['D']::text[], 'جدول تدبير حصص الكتابة في السنة الأولى: الوحدات الأولى والثانية والثالثة «حرف واحد في الأسبوع»، والوحدتان الرابعة والخامسة «حرفان في الأسبوع»، والوحدة السادسة دعم سنوي عام (ص. 90؛ والتدرج نفسه في القراءة، ص. 82).', 'qcm', 'third_party', 'https://www.wadifa-info.com/fr/modele-concours/2195/modele-de-concours-professeurs-de-l-enseignement-primaire-2e-grade-crmef-specialite-doub', true, 'manasseb لم يقترح جوابا؛ الجواب من wadifa-info.')
