-- أسئلة امتحان: ديداكتيك اللغة العربية — Q25
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_ar_jan_q25', 'exam_primary_2023_didactics_ar_jan', 25, 'التطبيقات الكتابية — موجهات', 'من بين موجهات التطبيقات الكتابية في السنة الرابعة:', false, '[{"id": "A", "text": "حصة واحدة في الأسبوع، التدرج، تطبيقات كتابية، التدرب على الإنتاج."}, {"id": "B", "text": "حصة واحدة في أسبوعين، التدرج، تطبيقات كتابية، التدرب على الإنتاج."}, {"id": "C", "text": "حصتان في الأسبوع، التدرج، التعبير الكتابي، التدرب على الإنتاج."}, {"id": "D", "text": "حصتان في أسبوعين، الشكل، تطبيقات كتابية، التدرب على الإنتاج."}]'::jsonb, ARRAY['A']::text[], 'موجهات التطبيقات الكتابية في السنة الرابعة: «تُخصص لها حصة واحدة كل أسبوع؛ يعتمد فيها نص قصير مرتبط بالمجال لضبط بعض كلماته أو جمله بالشكل؛ يعتمد مبدأ التدرج في ضبط الكلمات...؛ يفسح المجال للتمارين الكتابية...؛ يتدرب المتعلمون والمتعلمات على الإنتاج» (ص. 120). الاختياران C وD (حصتان) يخلطان بتدبير الشكل والتطبيقات في السنتين الخامسة والسادسة (حصتان في أسبوعين متتاليين، ص. 126)، وB («كل أسبوعين») غير وارد.', 'qcm', 'third_party', 'https://www.wadifa-info.com/fr/modele-concours/2195/modele-de-concours-professeurs-de-l-enseignement-primaire-2e-grade-crmef-specialite-doub', true, 'manasseb لم يقترح جوابا؛ الجواب من wadifa-info.')
