VALUES ('exam_primary_2023_didactics_fr_jan_q26', 'exam_primary_2023_didactics_fr_jan', 26, 'Situation didactique', 'Quelle est la proposition qui correspond à la fonction de la situation didactique ?', false, '[{"id": "A", "text": "La situation didactique sert à amener les élèves à évaluer, par eux-mêmes, les savoirs à enseigner."}, {"id": "B", "text": "La situation didactique sert à amener les élèves à sélectionner les contenus à enseigner."}, {"id": "C", "text": "La situation didactique sert à enseigner, et à amener les élèves à construire des apprentissages."}, {"id": "D", "text": "La situation didactique sert à amener les élèves à répertorier les difficultés d''enseignement."}]'::jsonb, ARRAY['C']::text[], 'La situation didactique est le dispositif par lequel l''enseignant enseigne et fait construire les apprentissages aux élèves.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
