-- أسئلة امتحان: ديداكتيك اللغة الفرنسية — Q27
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q27', 'exam_primary_2023_didactics_fr_jan', 27, 'Triangle didactique', 'Parmi les propositions suivantes, quelle est celle qui correspond à la définition du triangle didactique ?', false, '[{"id": "A", "text": "Le triangle didactique est un dessin symbolique qui représente linéairement les relations entre l''enseignant et l''élève, et définit explicitement les tâches de chacun d''eux."}, {"id": "B", "text": "Le triangle didactique est un dessin symbolique qui représente les relations entre l''enseignant, l''élève et le savoir dans un environnement scolaire à un moment déterminé."}, {"id": "C", "text": "Le triangle didactique est un dessin symbolique qui représente linéairement les relations entre l''enseignant et le savoir dans un environnement scolaire à un moment déterminé."}, {"id": "D", "text": "Le triangle didactique est un dessin symbolique qui représente linéairement les relations entre l''élève et le savoir dans un environnement pédagogique à un moment déterminé."}]'::jsonb, ARRAY['B']::text[], 'Le triangle didactique (Houssaye) relie trois pôles : enseignant, élève, savoir ; les autres propositions n''en retiennent que deux.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
