-- أسئلة امتحان: ديداكتيك اللغة الفرنسية — Q28
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q28', 'exam_primary_2023_didactics_fr_jan', 28, 'Transposition didactique', 'Parmi les propositions suivantes, quelle est celle qui correspond à la définition de la transposition didactique ?', false, '[{"id": "A", "text": "La transposition didactique est le processus de transformation du savoir savant en savoir-faire et savoir-être à enseigner, abstraction faite des objectifs pédagogiques et des caractéristiques cognitives des apprenants."}, {"id": "B", "text": "La transposition didactique est le processus de transformation du savoir à enseigner en savoir savant, abstraction faite des intentions pédagogiques et du cadre où se réalisent les activités d''enseignement/apprentissage."}, {"id": "C", "text": "La transposition didactique est le processus de transformation du savoir à enseigner en savoir savant en prenant en considération la formation des enseignants et le cadre où se réalise l''action pédagogique."}, {"id": "D", "text": "La transposition didactique est le processus de transformation du savoir savant en savoir à enseigner en prenant en considération les objectifs pédagogiques et les caractéristiques cognitives des apprenants."}]'::jsonb, ARRAY['D']::text[], 'Chevallard : passage du savoir savant au savoir à enseigner, adapté aux objectifs et aux apprenants.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
