-- أسئلة امتحان: ديداكتيك اللغة الفرنسية — Q29
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q29', 'exam_primary_2023_didactics_fr_jan', 29, 'Discours oral', 'Dans quelle liste les éléments indiqués constituent-ils tous des caractéristiques du discours dans des situations de communication orale ?', false, '[{"id": "A", "text": "Les fréquences des signaux de régulation - L''emploi des signes de ponctuation - La concomitance entre la planification et l''émission du discours - Une réception plus aisée - Les traits prosodiques - Les phénomènes de « disfluence »."}, {"id": "B", "text": "L''absence de contact direct - Le caractère linéaire et temporel - Le phénomène de transformation phonétique - Le suremploi de déictiques - Les répétitions aspectuelles - Les traits prosodiques."}, {"id": "C", "text": "Le caractère linéaire et temporel - Les traits prosodiques - La difficulté à segmenter le flux sonore - Le suremploi de déictiques - L''élaboration d''un discours en continu - Les répétitions aspectuelles."}, {"id": "D", "text": "Les traits prosodiques - La difficulté à segmenter le flux sonore - Le phénomène de transformation phonétique - Le suremploi de déictiques - L''organisation rigoureuse des signes graphiques - Le caractère linéaire et temporel."}]'::jsonb, ARRAY['C']::text[], 'Tous les éléments relèvent de l''oral ; A (ponctuation), B (absence de contact direct) et D (signes graphiques) contiennent des traits de l''écrit.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
ON CONFLICT (id) DO UPDATE SET 
    text = EXCLUDED.text,
    options = EXCLUDED.options,
