INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q30', 'exam_primary_2023_didactics_fr_jan', 30, 'Actes de langage — conseil', 'Lors d''une activité orale, une professeure a posé aux élèves la question ci-dessous : À quel acte de langage correspond l''énoncé suivant ? « Si j''étais à ta place, je ferais du sport quotidiennement. » Laquelle des réponses, ci-dessous, convient à la question de cette professeure ?', false, '[{"id": "A", "text": "Donner un conseil."}, {"id": "B", "text": "Exprimer une obligation."}, {"id": "C", "text": "Exprimer une demande."}, {"id": "D", "text": "Exprimer une interdiction."}]'::jsonb, ARRAY['A']::text[], '« Si j''étais à ta place… » + conditionnel = formule de conseil.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
