-- أسئلة امتحان: ديداكتيك اللغة الفرنسية — Q31
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q31', 'exam_primary_2023_didactics_fr_jan', 31, 'Actes de langage — interdiction', 'Un professeur envisage d''amener les élèves d''une classe de la 5e année de l''enseignement primaire à identifier les moyens linguistiques servant à réaliser l''acte de langage « Exprimer une interdiction ». Dans quelle liste les moyens linguistiques indiqués sont-ils tous appropriés à la réalisation de cet acte de langage ?', false, '[{"id": "A", "text": "... être obligé de ... - Il faut ... - ... avoir l''obligation de ... - ... être tenu de ..."}, {"id": "B", "text": "Il ne faut pas ... - Interdiction de ... - Il est interdit de ... - Il est défendu de ..."}, {"id": "C", "text": "Il vaudrait mieux ... - Il est recommandé de ... - ... avoir l''obligation de ... - Il importe de ..."}, {"id": "D", "text": "Il vaut mieux ... - ... être tenu de ... - Ça me ferait plaisir de ... - Ce serait bien de ..."}]'::jsonb, ARRAY['B']::text[], 'Seule liste composée uniquement de tournures d''interdiction.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
