-- أسئلة امتحان: ديداكتيك اللغة الفرنسية — Q32
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q32', 'exam_primary_2023_didactics_fr_jan', 32, 'Oral — stratégies de réception', 'Dans quelle liste les éléments indiqués sont-ils tous des stratégies appropriées à la réception de l''oral ?', false, '[{"id": "A", "text": "Recourir à des gestes, des mimiques, des exemples, des illustrations, des objets pour appuyer ses paroles. - Interpréter le langage non verbal. - Prendre son temps, parler lentement. - Émettre des hypothèses sur ce qui n''a pas été compris."}, {"id": "B", "text": "Repérer les sons, distinguer les mots - Interpréter le langage non verbal. - Adopter une posture d''écoute - Écouter attentivement les noms propres et les voix pour identifier les personnages."}, {"id": "C", "text": "Décoder, en contexte, les mots nouveaux rencontrés dans un texte. - Prendre son temps, parler lentement. - Adopter une posture d''écoute. - Écouter attentivement les noms propres et les voix pour identifier les personnages."}, {"id": "D", "text": "Écouter attentivement les noms propres et les voix pour identifier les personnages. - Recourir à des éléments prosodiques pour appuyer ses propos. - Interpréter le langage non verbal. - Prendre son temps, parler lentement."}]'::jsonb, ARRAY['B']::text[], 'Stratégies d''écoute ; A et D mêlent des stratégies de production, C une stratégie de lecture (décoder des mots dans un texte).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
