-- أسئلة امتحان: ديداكتيك اللغة الفرنسية — Q33
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q33', 'exam_primary_2023_didactics_fr_jan', 33, 'Actes de langage — ordre', 'Lors de l''évaluation d''une activité orale, un professeur a demandé aux élèves de produire des énoncés pour exprimer un ordre. Parmi les énoncés ci-dessous, produits par les élèves, quel est celui qui convient à la consigne du professeur ?', false, '[{"id": "A", "text": "Nous aimerions partir en voyage."}, {"id": "B", "text": "Il ne faut pas allumer le feu dans la forêt."}, {"id": "C", "text": "Faites vos devoirs."}, {"id": "D", "text": "Si j''étais à ta place, je continuerais mes études."}]'::jsonb, ARRAY['C']::text[], 'L''impératif « Faites vos devoirs » exprime un ordre.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
