-- أسئلة امتحان: ديداكتيك اللغة الفرنسية — Q34
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q34', 'exam_primary_2023_didactics_fr_jan', 34, 'Oral — capacités de production', 'Dans quelle liste les éléments indiqués sont-ils tous des capacités appropriées à la production de l''oral ?', false, '[{"id": "A", "text": "Dire de mémoire des comptines, des chansons, des poèmes, des textes et des contes. - Exprimer oralement son opinion sur un énoncé entendu. - Associer le verbal et le non verbal. - S''exprimer, de manière audible, pour manifester sa compréhension d''un texte entendu."}, {"id": "B", "text": "S''exprimer, de manière audible, pour manifester sa compréhension d''un texte entendu. - Dire de mémoire des comptines, des chansons, des poèmes, des textes et des contes. - Suivre un énoncé dit lentement. - Exprimer oralement son opinion sur un énoncé entendu."}, {"id": "C", "text": "Dire de mémoire des comptines, des chansons, des poèmes, des textes et des contes. - Exprimer son opinion sur un énoncé entendu. - Comprendre l''état attitudinal et émotionnel du locuteur à partir des caractéristiques prosodiques de sa parole. - S''exprimer, de manière audible, pour manifester sa compréhension d''un texte entendu."}, {"id": "D", "text": "Maitriser les tracés de base de l''écriture - Dire de mémoire des comptines, des chansons, des poèmes, des textes et des contes. - Exprimer oralement son opinion sur un énoncé entendu. - S''exprimer, de manière audible, pour manifester sa compréhension d''un texte entendu."}]'::jsonb, ARRAY['A']::text[], 'B contient une capacité de réception (suivre un énoncé), C une capacité de compréhension, D une capacité d''écriture.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
