-- أسئلة امتحان: ديداكتيك اللغة الفرنسية — Q35
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q35', 'exam_primary_2023_didactics_fr_jan', 35, 'Oral — étapes méthodologiques', 'Une professeure procédera à la planification d''une activité orale destinée aux élèves d''une classe de la 4e année de l''enseignement primaire. Dans quelle liste les étapes méthodologiques, que cette professeure mentionnerait sur sa fiche pédagogique, sont-elles cohérentes et logiquement enchaînées ?', false, '[{"id": "A", "text": "Réception / Compréhension - Observation / Découverte - Réemploi du lexique et des structures - Production - Évaluation et soutien"}, {"id": "B", "text": "Réemploi du lexique et des structures - Observation / Découverte - Réception / Compréhension - Production - Évaluation et soutien"}, {"id": "C", "text": "Observation / Découverte - Réception / Compréhension - Réemploi du lexique et des structures - Production - Évaluation et soutien"}, {"id": "D", "text": "Observation / Découverte - Réemploi du lexique et des structures - Réception / Compréhension - Production - Évaluation et soutien"}]'::jsonb, ARRAY['A']::text[], 'Dans les guides marocains, l''activité orale commence par l''écoute/compréhension du support, puis l''observation des actes de langage, le réemploi, la production, l''évaluation et le soutien. C''est l''ordre des guides pédagogiques marocains les plus récents ; C est possible selon le guide utilisé.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان. تعارض منشور: mesconcours.ma يقترح C (Observation / Découverte - Réception / Compréhension - Réemploi du lexique et des structures - Production - Évaluation et soutien)، مع وضع ⚠ على السؤال (الترتيب يعتمد على الدليل المعتمد). الجواب المعتمد هنا هو جواب manasseb (A).')
