-- أسئلة امتحان: ديداكتيك اللغة الفرنسية — Q36
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q36', 'exam_primary_2023_didactics_fr_jan', 36, 'Oral — difficulté d’articulation', 'Lors de la mise en œuvre d''une activité orale, un professeur constate que des élèves d''une classe de la 3e année de l''enseignement primaire confondent l''articulation des phonèmes [e] et [ɛ]. Quelle est la proposition la plus appropriée au traitement immédiat de cette difficulté ?', false, '[{"id": "A", "text": "Inciter les élèves, qui confondent l''articulation de [e] et [ɛ], à distinguer les graphèmes correspondant à ces deux phonèmes et à améliorer, par eux-mêmes, leur prononciation."}, {"id": "B", "text": "Demander aux élèves, qui confondent l''articulation des phonèmes [e] et [ɛ], de faire de leur mieux pour remédier ultérieurement à cette difficulté et améliorer leur prononciation."}, {"id": "C", "text": "Dire respectivement des mots contenant le phonème [e] et d''autres contenant le phonème [ɛ] en exagérant l''articulation de ces deux phonèmes, puis faire répéter plusieurs fois ces mots."}, {"id": "D", "text": "Écrire au tableau des mots contenant les graphèmes correspondant au phonème [e] et d''autres contenant les graphèmes qui correspondent au phonème [ɛ], puis les lire."}]'::jsonb, ARRAY['C']::text[], 'Le traitement immédiat d''une difficulté d''articulation se fait à l''oral : modèle exagéré puis répétition.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
