INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q38', 'exam_primary_2023_didactics_fr_jan', 38, 'Lecture — étapes méthodologiques', 'Un professeur envisage de planifier une activité de lecture destinée aux élèves d''une classe de la 6e année de l''enseignement primaire. Quelle est la liste où les étapes méthodologiques, que ce professeur indiquerait sur sa fiche de préparation, sont cohérentes et logiquement enchaînées ?', false, '[{"id": "A", "text": "Découverte / Prise d''indices et formulation des hypothèses de lecture - Interaction avec le texte / Compréhension / Construction du sens - Réaction au texte - Évaluation"}, {"id": "B", "text": "Interaction avec le texte / Compréhension / Construction du sens - Réaction au texte - Découverte / Prise d''indices et formulation des hypothèses de lecture - Évaluation"}, {"id": "C", "text": "Découverte / Prise d''indices et formulation des hypothèses de lecture - Réaction au texte - Interaction avec le texte / Compréhension / Construction du sens - Évaluation"}, {"id": "D", "text": "Découverte / Prise d''indices et formulation des hypothèses de lecture - Évaluation - Interaction avec le texte / Compréhension / Construction du sens - Réaction au texte"}]'::jsonb, ARRAY['A']::text[], 'Ordre logique : découverte/hypothèses → compréhension/construction du sens → réaction au texte → évaluation.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
