INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q40', 'exam_primary_2023_didactics_fr_jan', 40, 'Lecture — stratégies de compréhension', 'Quelle est la liste où les éléments indiqués sont tous des stratégies relatives à la compréhension de l''écrit ?', false, '[{"id": "A", "text": "Interpréter les gestes et les mimiques. - Entrer dans le texte en utilisant le paratexte. - Repérer la forme du texte. - Utiliser les indices relatifs à la ponctuation."}, {"id": "B", "text": "Planifier sa manière de lire le texte. - Entrer dans le texte en utilisant le paratexte. - Repérer la forme du texte. - Reconnaitre globalement les mots fréquents."}, {"id": "C", "text": "Retenir l''essentiel de l''information véhiculée par un texte. - Comprendre le sens d''un énoncé entendu. - Repérer la forme du texte. - Reformuler un énoncé entendu."}, {"id": "D", "text": "Se rappeler des modèles d''écriture déjà vus. - Interpréter un énoncé entendu. - Repérer la forme du texte. - Anticiper l''organisation du texte à produire."}]'::jsonb, ARRAY['B']::text[], 'Seule liste uniquement composée de stratégies de lecture ; les autres mêlent oral ou production écrite.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
