INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q42', 'exam_primary_2023_didactics_fr_jan', 42, 'Lecture — sens littéral', 'Lors de la mise en œuvre d''une activité de lecture, un professeur demande aux élèves de lire silencieusement le texte, et d''y relever les informations explicites. Quel est l''objectif visé par l''intervention de ce professeur ?', false, '[{"id": "A", "text": "Amener les élèves à construire le sens littéral du texte."}, {"id": "B", "text": "Amener les élèves à formuler des hypothèses de lecture."}, {"id": "C", "text": "Amener les élèves à exprimer leur avis sur le texte."}, {"id": "D", "text": "Amener les élèves à interpréter des passages du texte."}]'::jsonb, ARRAY['A']::text[], 'Relever les informations explicites = construire le sens littéral.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
