-- أسئلة امتحان: ديداكتيك اللغة الفرنسية — Q43
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q43', 'exam_primary_2023_didactics_fr_jan', 43, 'Lecture — capacités de lecture', 'Dans quelle liste les éléments indiqués sont-ils tous des capacités de lecture ?', false, '[{"id": "A", "text": "Discriminer des phonèmes et des syllabes. - Lire des textes et des supports iconiques. - Identifier les phonèmes et les graphies qui leur correspondent. - Maitriser les tracés de base de l''écriture."}, {"id": "B", "text": "Identifier les phonèmes et les graphies qui leur correspondent. - Lire des syllabes et des mots. - Lire des textes et des supports iconiques. - Faire des inférences directes."}, {"id": "C", "text": "Identifier les phonèmes et les graphies qui leur correspondent. - Identifier les formes de lettres. - Associer le verbal et le non verbal. - Lire des mots et des phrases."}, {"id": "D", "text": "Identifier les formes de lettres. - Lire des lettres et des syllabes. - Identifier les phonèmes et les graphèmes qui leur correspondent. - Comprendre le sens d''un énoncé entendu."}]'::jsonb, ARRAY['B']::text[], 'A et C contiennent des capacités d''écriture ou d''oral, D une capacité d''écoute.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
