-- أسئلة امتحان: ديداكتيك اللغة الفرنسية — Q45
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q45', 'exam_primary_2023_didactics_fr_jan', 45, 'Production écrite — type de texte', 'Voici une consigne relative à une activité de production écrite : « En te promenant dans la forêt en compagnie de tes parents, tu as constaté que des enfants cassent les branches d''un arbre. Écris, pour le journal de ton école, un texte où tu incites tes camarades à protéger les arbres. » Quel est le type de texte visé par cette activité de production écrite ?', false, '[{"id": "A", "text": "Narratif"}, {"id": "B", "text": "Injonctif"}, {"id": "C", "text": "Descriptif"}, {"id": "D", "text": "Explicatif"}]'::jsonb, ARRAY['B']::text[], 'Inciter les camarades à protéger les arbres = texte injonctif/incitatif. Inciter ses camarades à agir relève du texte injonctif (incitatif) ; le type argumentatif, possible aussi, n''est pas proposé.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان.')
