-- أسئلة امتحان: ديداكتيك اللغة الفرنسية — Q46
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q46', 'exam_primary_2023_didactics_fr_jan', 46, 'Production écrite — stratégies', 'Quelle est la liste où les éléments indiqués sont tous des stratégies appropriées à la production écrite ?', false, '[{"id": "A", "text": "Écrire, au fur et à mesure, les idées qui surviennent. - Utiliser de nouveaux mots ou de nouvelles expressions. - Déduire la visée du texte. - Rédiger un premier jet à partir d''idées formulées mentalement."}, {"id": "B", "text": "Prendre des risques de formulation. - Émettre des hypothèses pour anticiper sur le sens et la fonction du texte. - Rédiger un premier jet à partir d''idées formulées mentalement. - Écrire, au fur et à mesure, les idées qui surviennent."}, {"id": "C", "text": "Utiliser un déclencheur pour stimuler son imaginaire. - Rédiger un premier jet à partir d''idées formulées mentalement. - Écrire, au fur et à mesure, les idées qui surviennent. - Anticiper l''organisation du texte à produire."}, {"id": "D", "text": "Utiliser de nouveaux mots ou de nouvelles expressions. - Anticiper l''organisation du texte à produire. - Interpréter le langage non verbal. - Utiliser un déclencheur pour stimuler son imaginaire."}]'::jsonb, ARRAY['C']::text[], 'Toutes sont des stratégies d''écriture ; A (déduire la visée), B (hypothèses sur le sens) et D (langage non verbal) contiennent des stratégies de lecture ou d''oral.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
