-- أسئلة امتحان: ديداكتيك اللغة الفرنسية — Q47
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q47', 'exam_primary_2023_didactics_fr_jan', 47, 'Production écrite — critères de correction', 'Un professeur procédera à la correction des textes écrits par les élèves d''une classe de la 6e année de l''enseignement primaire lors d''une activité de production écrite. Quelle est la liste où les critères indiqués sont tous appropriés à la réalisation de cette tâche de correction ?', false, '[{"id": "A", "text": "Le respect de la consigne - La prosodie - La présentation matérielle de la production - Les formes verbales utilisées"}, {"id": "B", "text": "La lisibilité du texte produit - Le respect des règles grammaticales - Les groupes de souffle - Le nombre de phrases produites"}, {"id": "C", "text": "La présentation matérielle de la production - Le nombre de phrases produites - L''intonation - Le lexique employé"}, {"id": "D", "text": "Le respect de la consigne - La correction de la langue - La cohérence du texte produit - La présentation matérielle de la production"}]'::jsonb, ARRAY['D']::text[], 'Critères propres à l''écrit ; prosodie, groupes de souffle et intonation relèvent de l''oral.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
