-- أسئلة امتحان: ديداكتيك اللغة الفرنسية — Q48
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q48', 'exam_primary_2023_didactics_fr_jan', 48, 'Production écrite — capacités', 'Dans quelle liste les éléments indiqués sont-ils tous des capacités appropriées à la production de l''écrit ?', false, '[{"id": "A", "text": "Copier sans erreurs, en écriture cursive, des mots, des phrases et des textes. - Maitriser les tracés de base de l''écriture. - Écrire, sous dictée, des mots, des phrases ou des textes. - Produire, par écrit, des phrases simples ou des textes courts, à partir de supports iconiques et/ou graphiques."}, {"id": "B", "text": "Déduire le sens d''expressions ou de mots nouveaux d''après le contexte. - Maitriser les tracés de base de l''écriture. - Reconstituer des phrases et/ou des textes courts. - Copier sans erreurs, en écriture cursive, des mots, des phrases et des textes."}, {"id": "C", "text": "Reconstituer des phrases et/ou des textes courts. - Maitriser les tracés de base de l''écriture. - Copier sans erreurs, en écriture cursive, des mots, des phrases et des textes. - Adapter sa façon de dire/parler à ses interlocuteurs."}, {"id": "D", "text": "Faire attention au fond sonore ou aux bruits pour situer la scène. - Reconstituer des phrases et/ou des textes courts. - Maitriser les tracés de base de l''écriture. - Copier sans erreurs, en écriture cursive, des mots, des phrases et des textes."}]'::jsonb, ARRAY['A']::text[], 'B (déduire le sens), C (adapter sa façon de parler) et D (fond sonore) contiennent un intrus.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
