INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q49', 'exam_primary_2023_didactics_fr_jan', 49, 'Écriture — étapes méthodologiques', 'Un professeur procédera à l''élaboration d''une fiche pédagogique d''une activité d''écriture destinée aux élèves d''une classe de la 2e année de l''enseignement primaire. Dans quelle liste les étapes méthodologiques, que ce professeur indiquerait sur sa fiche pédagogique, sont-elles cohérentes et logiquement enchaînées ?', false, '[{"id": "A", "text": "Entraînement / Application - Observation / Découverte - Évaluation / Correction - Réalisation / Production"}, {"id": "B", "text": "Entraînement / Application - Évaluation / Correction - Observation / Découverte - Réalisation / Production"}, {"id": "C", "text": "Observation / Découverte - Entraînement / Application - Réalisation / Production - Évaluation / Correction"}, {"id": "D", "text": "Observation / Découverte - Réalisation / Production - Évaluation / Correction - Entraînement / Application"}]'::jsonb, ARRAY['C']::text[], 'Progression : observation → entraînement → production → évaluation/correction.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, NULL)
