INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_fr_jan_q50', 'exam_primary_2023_didactics_fr_jan', 50, 'Production écrite — phases', 'Lors d''une activité de production écrite, une professeure procède à l''exploitation d''un texte narratif, déjà étudié en lecture, pour amener les élèves à en identifier la structure et les caractéristiques. À quelle phase de cette activité de production écrite l''intervention de cette professeure renvoie-t-elle ?', false, '[{"id": "A", "text": "à la phase d''entrainement à l''écriture"}, {"id": "B", "text": "à la phase préparatoire orale"}, {"id": "C", "text": "à la phase d''évaluation des productions"}, {"id": "D", "text": "à la phase d''écriture des premiers jets"}]'::jsonb, ARRAY['B']::text[], 'Analyser un texte modèle pour en dégager la structure prépare l''écriture : c''est la phase préparatoire (orale). L''analyse d''un texte modèle se fait avant l''entraînement et le premier jet ; certains guides la placent dans la phase d''entraînement (A).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41822-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان. mesconcours.ma يوافق الجواب B لكنه يضع ⚠ على السؤال (تسمية المراحل تختلف حسب الدليل المعتمد).')
