VALUES ('exam_primary_2023_didactics_maths_jan_q51', 'exam_primary_2023_didactics_maths_jan', 51, 'التعاقد الديدكتيكي', 'التعاقد الديدكتيكي هو:', false, '[{"id": "A", "text": "مجموع المعارف التي ينقلها المدرس(ة) إلى التلميذ(ة)، وجميع تمثلات التلميذ(ة) التي يسعى المدرس(ة) إلى إبرازها."}, {"id": "B", "text": "مجموع سلوكيات المدرس(ة) المتوقعة من التلميذ(ة)، وجميع سلوكيات التلميذ(ة) المتوقعة من المدرس(ة)."}, {"id": "C", "text": "مجموع الكفايات المهنية التي يعتمدها المدرس(ة) في نقلها للمعرفة إلى التلميذ(ة)، ومجموع الأنشطة المنجزة من طرف هذا الأخير."}, {"id": "D", "text": "مجموع المعارف التي ينقلها المدرس(ة) إلى التلميذ(ة) ومجموع الكفايات التي ينميها لديه."}]'::jsonb, ARRAY['B']::text[], 'التعاقد الديدكتيكي (بروسو): مجموع السلوكات (الضمنية غالبا) التي ينتظرها كل من المدرس والتلميذ من الآخر.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42529-enseignant-2023/', true, NULL)
