VALUES ('exam_primary_2023_didactics_maths_jan_q54', 'exam_primary_2023_didactics_maths_jan', 54, 'التقويم — استثمار النتائج', 'يعتبر التقويم وسيلة للكشف عن مواطن القوة من أجل تثمينها، ومواطن الضعف من أجل تجاوزها، ويتم استثمار نتائج التقويم من خلال آليتين هما:', false, '[{"id": "A", "text": "آلية الدعم التربوي وآلية المعالجة المركزة."}, {"id": "B", "text": "آلية التقويم الدقيق وآلية الدعم التربوي."}, {"id": "C", "text": "آلية تخطيط الدروس وآلية تحسين تدبير الحصص."}, {"id": "D", "text": "آلية الدعم والمعالجة وآلية تحسين طرق التدريس."}]'::jsonb, ARRAY['D']::text[], 'تستثمر النتائج في دعم المتعلمين ومعالجة تعثراتهم، وفي تعديل وتحسين طرق التدريس.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42529-enseignant-2023/', true, NULL)
