-- أسئلة امتحان: ديداكتيك الرياضيات — Q55
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_maths_jan_q55', 'exam_primary_2023_didactics_maths_jan', 55, 'نظرية الوضعيات', 'تعتبر نظرية الوضعيات نموذجا، يُمكن المدرس من اختيار وتدبير وضعيات تعليمية تعلمية، تتيح له بناء المعارف الرياضياتية الجديدة. تنبني هذه النظرية على فرضية مفادها أن التلميذ تكون له:', false, '[{"id": "A", "text": "أخطاء معرفية يتم تصحيحها وتجاوزها من خلال وضعيات ديدكتيكية."}, {"id": "B", "text": "تمثلات خاطئة عن تعلمات سابقة يتم تعديلها ودعمها من خلال وضعيات ديدكتيكية."}, {"id": "C", "text": "تمثلات قبلية بخصوص المفاهيم الرياضياتية المراد اكتسابها أو معارف غير كافية، يطرأ عليها تحولات ويعاد تنظيمها وترتيبها من خلال وضعيات ديدكتيكية."}, {"id": "D", "text": "معارف سابقة غير ملائمة يتم تعويضها باعتماد وضعيات ديدكتيكية."}]'::jsonb, ARRAY['C']::text[], 'تنطلق نظرية الوضعيات من أن المعرفة تبنى بتكييف وإعادة تنظيم المعارف والتمثلات السابقة.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42529-enseignant-2023/', true, NULL)
