-- أسئلة امتحان: ديداكتيك الرياضيات — Q56
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_maths_jan_q56', 'exam_primary_2023_didactics_maths_jan', 56, 'الوضعية 1 — طبيعة الوضعية', 'الوضعية 1: أراد عبد الله تغليف هدية لصديقه بورق وشريط تزيين الهدايا. (علبة على شكل متوازي مستطيلات أبعادها 50cm و30cm و20cm؛ ويخصص 10cm للعقدة والقطعة المتبقية) ما القياس الأدنى لحلول شريط تزيين هذه الهدية؟ طبيعة الوضعية المقترحة من طرف الأستاذ هي:', false, '[{"id": "A", "text": "وضعية ديدكتيكية."}, {"id": "B", "text": "تمرين تطبيقي."}, {"id": "C", "text": "وضعية إدماجية."}, {"id": "D", "text": "وضعية تشخيص المكتسبات."}]'::jsonb, ARRAY['C']::text[], 'الوضعية سياقية تتطلب تعبئة موارد مكتسبة من مجالات متعددة (القياس، الهندسة، الحساب): وضعية إدماجية. الوضعية تعبئ موارد من القياس والهندسة والحساب في سياق واقعي، وهذه سمة الوضعية الإدماجية؛ قد يعتبرها البعض «وضعية ديداكتيكية» (A).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42529-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان.')
