VALUES ('exam_primary_2023_didactics_maths_jan_q57', 'exam_primary_2023_didactics_maths_jan', 57, 'الوضعية 1 — المعينات الديدكتيكية', 'الوضعية 1: أراد عبد الله تغليف هدية لصديقه بورق وشريط تزيين الهدايا. (علبة على شكل متوازي مستطيلات أبعادها 50cm و30cm و20cm؛ ويخصص 10cm للعقدة والقطعة المتبقية) ما القياس الأدنى لحلول شريط تزيين هذه الهدية؟ المعينات الديدكتيكية المساعدة على فهم الوضعية أعلاه هي:', false, '[{"id": "A", "text": "علبة على شكل مكعب – شريط – ورقة التزيين – بركار."}, {"id": "B", "text": "علبة ذات أوجه على شكل معين – ورقة التزيين – مسطرة – مقص."}, {"id": "C", "text": "علبة ذات 3 أوجه مربعة وأخرى مستطيلة – مقص – شريط – وورق التزيين – مسطرة."}, {"id": "D", "text": "علبة على شكل متوازي المستطيلات – ورقة التزيين – شريط التزيين."}]'::jsonb, ARRAY['D']::text[], 'الهدية علبة على شكل متوازي مستطيلات، مع ورق وشريط التزيين.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42529-enseignant-2023/', true, NULL)
