VALUES ('exam_primary_2023_didactics_maths_jan_q58', 'exam_primary_2023_didactics_maths_jan', 58, 'الوضعية 1 — المجالات الرياضياتية', 'الوضعية 1: أراد عبد الله تغليف هدية لصديقه بورق وشريط تزيين الهدايا. (علبة على شكل متوازي مستطيلات أبعادها 50cm و30cm و20cm؛ ويخصص 10cm للعقدة والقطعة المتبقية) ما القياس الأدنى لحلول شريط تزيين هذه الهدية؟ من أي مجال أو مجالات رياضياتية سيتم استثمار الموارد المناسبة لحل هذه الوضعية:', false, '[{"id": "A", "text": "مجال القياس ومجال الهندسة وحل المسائل."}, {"id": "B", "text": "مجال الأعداد والحساب ومجال الهندسة وحل المسائل."}, {"id": "C", "text": "مجال الأعداد والحساب ومجال القياس."}, {"id": "D", "text": "مجال الهندسة ومجال القياس ومجال الأعداد والحساب."}]'::jsonb, ARRAY['D']::text[], 'التعرف على المجسم (الهندسة)، أطوال وتحويل الوحدات (القياس)، وجمع وضرب الأطوال (الأعداد والحساب).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42529-enseignant-2023/', true, NULL)
