INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_maths_jan_q60', 'exam_primary_2023_didactics_maths_jan', 60, 'العدد الصحيح الطبيعي — بناء العدد', 'لبناء العدد الصحيح الطبيعي كرئيسي مجموعة، تُستعمل المفاهيم الآتية:', false, '[{"id": "A", "text": "الخط المغلق/المفتوح، وعناصر المجموعة، عدد العناصر."}, {"id": "B", "text": "الخط المغلق/المفتوح، داخل/خارج، التقادر، العدد الصحيح الطبيعي."}, {"id": "C", "text": "الخط المغلق/المفتوح، داخل/خارج، التواصل حدا بحد، عدد عناصر مجموعة."}, {"id": "D", "text": "الخط المغلق/المفتوح، داخل/خارج، التواصل حدا بحد، التقادر، أصناف التكافؤ."}]'::jsonb, ARRAY['D']::text[], 'العدد الطبيعي كرئيسي مجموعة يُبنى عبر التقابل حدا بحد والتقادر (تساوي الرئيسي) وأصناف التكافؤ. D هو الاقتراح الأشمل (التقابل حدا بحد، التقادر، أصناف التكافؤ)، وهي المفاهيم المعتمدة لبناء العدد كرئيسي مجموعة.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42529-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان.')
