INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_maths_jan_q63', 'exam_primary_2023_didactics_maths_jan', 63, 'الوضعية 2 — تدرج الكتلة', 'الوضعية 2: يُقدم المفهوم في مادة الرياضيات وفق تدرج يوافق مراحل النمو المعرفي للمتعلم ويتطور من مستوى دراسي معين إلى مستوى دراسي أعلى. يُقدم منهاج الرياضيات الكتلة، من خلال المضامين الآتية: ① أجزاء kg - ② العلاقة بين g وkg - ③ القنطار والطن - ④ مضاعفات kg. التدرج الصحيح المعتمد في تقديم الكتلة هو:', false, '[{"id": "A", "text": "③ ← ② ← ④ ← ①."}, {"id": "B", "text": "④ ← ① ← ③ ← ②."}, {"id": "C", "text": "① ← ② ← ④ ← ③."}, {"id": "D", "text": "② ← ① ← ④ ← ③."}]'::jsonb, ARRAY['C']::text[], '① أجزاء kg ثم ② العلاقة بين g وkg ثم ④ مضاعفات kg ثم ③ القنطار والطن. التدرج من الكيلوغرام وأجزائه إلى مضاعفاته ثم القنطار والطن هو المعتمد عادة؛ ترتيب ① و② قد يختلف حسب الكتاب المدرسي.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42529-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان.')
