INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_maths_jan_q65', 'exam_primary_2023_didactics_maths_jan', 65, 'القسمة الإقليدية — المعينات', 'تتم مقاربة مفهوم القسمة الإقليدية في المدرسة الابتدائية انطلاقا من وضعيات التوزيع بالتساوي. ومعالجة وضعيات التوزيع بالتساوي تسمح بالمناولة، سواء كانت باعتماد وسائل محسوسة أو شبه محسوسة، على أن يتم تواز مع هذا ربط مفهوم القسمة بالمعمليات التي يمكن أن تجري على الأعداد الممثلة للمقسوم والمقسوم عليه، للحصول على الخارج والباقي. ولهذا الغرض يمكن الاعتماد على معينات ديدكتيكية مناسبة من مثل:', false, '[{"id": "A", "text": "جدول التوزيع - المستقيم المدرج."}, {"id": "B", "text": "جدول التوزيع - الفروق المتساوية."}, {"id": "C", "text": "الفروق المتساوية - المستقيم العددي."}, {"id": "D", "text": "المستقيم المدرج - جدول العدد العشري."}]'::jsonb, ARRAY['A']::text[], 'جدول التوزيع والمستقيم المدرج (قفزات متساوية) يربطان التوزيع بالخارج والباقي. A هو الاقتراح الوحيد الذي يجمع جدول التوزيع والمستقيم المدرج (القفزات المتساوية) المذكورين في نص السؤال.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42529-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان.')
