INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_maths_jan_q68', 'exam_primary_2023_didactics_maths_jan', 68, 'الوضعية 4 — هدف الوضعية', 'الوضعية 4: قدمت أستاذة الوضعية الديدكتيكية الآتية: خلال إحدى المسابقات، حقق المتسابقون الثلاثة الأوائل في مسافة 300m الأوقات الآتية: أحمد 28,63 s، محمد 28,70 s، طه 28,67 s. بين ترتيب كل من المتسابقين الثلاثة؛ هل حقق هؤلاء المتسابقون الثلاثة توقيتا أكبر أو أصغر من 29 s؟ خلال مسابقة ثانية كانت النتائج كالآتي: أحمد 28,51 s، محمد 28,504 s، طه 28,5 s. حدد ترتيب كل من المتسابقين الثلاثة. تهدف هذه الوضعية إلى:', false, '[{"id": "A", "text": "بناء الأعداد العشرية."}, {"id": "B", "text": "تقديم ترتيب الأعداد العشرية."}, {"id": "C", "text": "تقويم ترتيب الأعداد العشرية."}, {"id": "D", "text": "بناء نظمة العدد العشري."}]'::jsonb, ARRAY['B']::text[], 'الوضعية تقدم وتبني ترتيب الأعداد العشرية مع تدرج الصعوبة. الوضعية تقدم المقارنة والترتيب بتدرج في الصعوبة (28,5 و28,504)؛ لكن قد تُعد أيضًا وضعية لتقويم الترتيب (C).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42529-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان.')
