VALUES ('exam_primary_2023_didactics_maths_jan_q71', 'exam_primary_2023_didactics_maths_jan', 71, 'الهندسة — التدرج', 'يتم تناول الهندسة من خلال الأشكال والأجسام وغيرهما في التعليم الابتدائي، وهذا التناول يتم باعتماد مبدأ التدرج واللولبية من مستوى دراسي إلى آخر. حدد تدرج التطرق للمفاهيم الأساسية في الهندسة في سلك التعليم الابتدائي:', false, '[{"id": "A", "text": "الخطوط، ثم الأشكال، فالمجسمات."}, {"id": "B", "text": "الأشكال، ثم الخطوط فالمجسمات."}, {"id": "C", "text": "المجسمات، ثم الخطوط، فالأشكال."}, {"id": "D", "text": "المجسمات، ثم الأشكال فالخطوط."}]'::jsonb, ARRAY['D']::text[], 'من المجسمات (العالم المحسوس) إلى الأشكال المستوية ثم الخطوط.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42529-enseignant-2023/', true, NULL)
