INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q76', 'exam_primary_2023_didactics_sciences_jan', 76, 'مهارات القرن 21 — المحتوى المعرفي', 'الوضعية 1: من ضمن أهداف تنمية مهارات القرن الواحد والعشرين، التمكن من المحتوى المعرفي العلمي (connaissance scientifique). الاقتراح الذي يناسب تنمية هذه المهارة هو:', false, '[{"id": "A", "text": "التمكن من التكيف مع متغيرات الحياة المدرسية واليومية والمجتمعية المستجدة."}, {"id": "B", "text": "تملك مهارات حل المشكلات والتفكير الناقد، والتواصل والتعاون، والإبداع والابتكار."}, {"id": "C", "text": "تملك المادة الأكاديمية لأنها عنصر أساسي لتنمية مختلف المهارات."}, {"id": "D", "text": "القدرة على استخدام التكنولوجيات الحديثة في تعلم المهارات."}]'::jsonb, ARRAY['C']::text[], 'التمكن من المحتوى المعرفي = امتلاك المادة الأكاديمية؛ الخيار B يخص مهارات التعلم والابتكار.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, NULL)
