INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q77', 'exam_primary_2023_didactics_sciences_jan', 77, 'المشروع التكنولوجي — خطوات الإنجاز', 'الوضعية 2: عند اتباع الخطوات المنهجية لإنجاز مشروع ذو طبيعة تكنولوجية منسجمة مع مواضيع النشاط العلمي، قام متعلم(ة) بإعداد بطاقة تقنية لهذا المشروع. الخطوة التي تناسب ما قام به المتعلم(ة) هي:', false, '[{"id": "A", "text": "إنشاء المشروع."}, {"id": "B", "text": "اختيار المشروع."}, {"id": "C", "text": "تطوير المشروع."}, {"id": "D", "text": "تصميم المشروع."}]'::jsonb, ARRAY['D']::text[], 'إعداد البطاقة التقنية يدخل في تصميم المشروع.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, 'ورقة الامتحان تكتب «مشروع ذو طبيعة» (هكذا في المسح)؛ ملف الحل وmesconcours.ma ينقلانها «مشروع ذي طبيعة».')
