INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q79', 'exam_primary_2023_didactics_sciences_jan', 79, 'باشلار — التمثلات', 'الوضعية 4: يقول غاستون باشلار (1884-1962): «غالبا ما اندهشت من سلوك المدرسين الذين يتصورون أن الفكر البشري يبدأ تعلمه كما يبدأ درسا... وقد فاتهم أن تلميذا يأتي وهو محمل بمعرفة مكتملة المعالم». المفهوم الديدكتيكي الذي يتحدث عنه غاستون باشلار هو:', false, '[{"id": "A", "text": "المفاهيم العلمية."}, {"id": "B", "text": "التعلمات المدرسية."}, {"id": "C", "text": "العوائق الإبستمولوجية."}, {"id": "D", "text": "التمثلات الفردية."}]'::jsonb, ARRAY['D']::text[], 'التلميذ يأتي بمعارف قبلية «مكتملة المعالم» : إنها التمثلات، وهي عند باشلار مصدر العوائق الإبستمولوجية. القولة تصف المعارف القبلية (التمثلات)، لكن المفهوم الذي اشتهر به باشلار هو العائق الإبستمولوجي (C)، فقد يكون هو الجواب المعتمد.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان.')
