INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q80', 'exam_primary_2023_didactics_sciences_jan', 80, 'الهدف العائق', 'الوضعية 5: يعتبر الهدف العائق من بين الأهداف التي يعتمدها المدرس(ة) لتخطيط التعلمات وله عدة مميزات. من مميزات الهدف العائق أنه:', false, '[{"id": "A", "text": "يُنتقى انطلاقا من التصورات الخاطئة للمتعلم(ة)."}, {"id": "B", "text": "يُنتقى من الأهداف المسطرة في المنهاج الدراسي."}, {"id": "C", "text": "يستحيل تجاوزه من خلال الأنشطة التعليمية التعلمية."}, {"id": "D", "text": "يسمح بتجاوز المستوى النمائي للمتعلم(ة)."}]'::jsonb, ARRAY['A']::text[], 'الهدف العائق (مارتيناند) يُختار انطلاقا من تمثلات المتعلمين الخاطئة القابلة للتجاوز.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, NULL)
