INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q81', 'exam_primary_2023_didactics_sciences_jan', 81, 'تمثلات المتعلمين — المنحى (ب)', 'المجال 2: مفاهيم ديدكتيكية وبرامج مادة النشاط العلمي. الوضعية 1: عند تدريس مادة النشاط العلمي، وخلال التعامل مع تمثلات المتعلمين(ات)، يمكن اعتماد منحيين مختلفين هما: المنحى (أ): يعتمد إجراء الكشف عن التمثلات أو التصورات قبل الشروع في إجراء الحصة (خلال الإعداد لها). المنحى (ب): يعتمد إجراء الكشف عن التمثلات أو التصورات خلال إجراء الحصة. المنحى (ب):', false, '[{"id": "A", "text": "يمنح الفرصة لصياغة جيدة للأهداف العوائق المرتبطة بالتمثلات أو التصورات."}, {"id": "B", "text": "يجعل مجابهة تمثلات أو تصورات المتعلمين(ات) تُجرى بشكل صريح خلال الحصة."}, {"id": "C", "text": "يساعد على إدراج تمثلات أو تصورات المتعلمين(ات) كموضوع لوضعية انطلاق الدرس."}, {"id": "D", "text": "يسمح باتخاذ التمثلات أو التصورات أرضية لإعداد جذاذة الدرس."}]'::jsonb, ARRAY['B']::text[], 'الكشف أثناء الحصة يسمح بمجابهة التمثلات بشكل صريح داخل القسم.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, NULL)
