VALUES ('exam_primary_2023_didactics_sciences_jan_q82', 'exam_primary_2023_didactics_sciences_jan', 82, 'العوائق الإبستمولوجية — العائق اللفظي', 'الوضعية 2: يمكن أن تُفسَّر تمثلات أو تصورات المتعلمين(ات) عن عوائق إبستمولوجية حددها غاستون باشلار في عدة أنواع. خلال إجراء الكشف عن تمثلات أو تصورات المتعلمين(ات) في حصة من مادة النشاط العلمي، حصل مدرس(ة) على التمثل أو التصور الآتي: الزبدة والشمع يذوبان تحت تأثير ارتفاع درجة الحرارة. العائق الإبستمولوجي الذي يرتبط بالتمثل أو التصور أعلاه هو:', false, '[{"id": "A", "text": "عائق التعميم."}, {"id": "B", "text": "العائق الجوهري."}, {"id": "C", "text": "العائق اللفظي."}, {"id": "D", "text": "العائق الاصطناعي."}]'::jsonb, ARRAY['C']::text[], 'الخلط بين «الذوبان» و«الانصهار» عائق لغوي (لفظي).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, NULL)
