-- أسئلة امتحان: ديداكتيك النشاط العلمي — Q83
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q83', 'exam_primary_2023_didactics_sciences_jan', 83, 'القوى والحركة — التتابع', 'الوضعية 3: ارتكز منهاج النشاط العلمي على مبدأي المدى والتتابع في صياغة المفاهيم العلمية حسب المستويات الدراسية. التتابع الصحيح المرتبط بتدريس القوى والحركة الذي يعتمده منهاج النشاط العلمي هو:', false, '[{"id": "A", "text": "يبين أن تحريك الأجسام أو إيقافها يتطلب قوة ← يميز بين الأجسام الساكنة والمتحركة ← يصنف القوى حسب نوعها ← يوضح كيف أن المسافة بين نقطة القوة ونقطة الارتكاز تؤثر على رفع الأجسام باعتماد الرافعة."}, {"id": "B", "text": "يميز بين الأجسام الساكنة والمتحركة ← يبين أن تحريك الأجسام أو إيقافها يتطلب قوة ← يصنف القوى حسب نوعها ← يوضح كيف أن المسافة بين نقطة القوة ونقطة الارتكاز تؤثر على رفع الأجسام باعتماد الرافعة."}, {"id": "C", "text": "يميز بين الأجسام الساكنة والمتحركة ← يبين أن تحريك الأجسام أو إيقافها يتطلب قوة ← يوضح كيف أن المسافة بين نقطة القوة ونقطة الارتكاز تؤثر على رفع الأجسام باعتماد الرافعة ← يصنف القوى حسب نوعها."}, {"id": "D", "text": "يصنف القوى حسب نوعها ← يميز بين الأجسام الساكنة والمتحركة ← يبين أن تحريك الأجسام أو إيقافها يتطلب قوة ← يوضح كيف أن المسافة بين نقطة القوة ونقطة الارتكاز تؤثر على رفع الأجسام باعتماد الرافعة."}]'::jsonb, ARRAY['B']::text[], 'من التمييز بين السكون والحركة، إلى دور القوة، ثم تصنيف القوى، ثم الرافعة (السنة السادسة).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, NULL)
