VALUES ('exam_primary_2023_didactics_sciences_jan_q84', 'exam_primary_2023_didactics_sciences_jan', 84, 'الغلاف الزمني — الدقائق الخمس', 'الوضعية 4: حسب التوجيهات التربوية والبرامج الدراسية الخاصة بمادة النشاط العلمي، مدة كل حصة من حصص مادة النشاط العلمي هي 60 دقيقة إلا خمس دقائق. تخصص الخمس دقائق لأجل:', false, '[{"id": "A", "text": "تسجيل أسماء المتغيبين من المتعلمين(ات)."}, {"id": "B", "text": "استعداد المتعلمين(ات) للخروج من القسم."}, {"id": "C", "text": "إنجاز نشاط ترفيهي مع المتعلمين(ات)."}, {"id": "D", "text": "تذكير المتعلمين(ات) بالواجبات المنزلية."}]'::jsonb, ARRAY['B']::text[], 'الدقائق الخمس للتنقل والاستعداد لمغادرة القسم. هذا هو الاستعمال المعتاد للدقائق الخمس في التوجيهات التربوية (التنقل والاستعداد للحصة الموالية).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان.')
