INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q85', 'exam_primary_2023_didactics_sciences_jan', 85, 'التقويم والدعم — الأسبوع الخامس', 'الوضعية 5: حسب التوجيهات التربوية، يدرج المدرس(ة) حصتين خلال أسابيع كل وحدة من وحدات مادة النشاط العلمي بسلك التعليم الابتدائي؛ الحصة الأولى موضوعها تقويم وتفييء المتعلمين(ات) حسب نوع التعثرات، والحصة الثانية موضوعها الدعم والمعالجة حسب نوع التعثرات. يتم إدراج هاتين الحصتين في كل وحدة خلال:', false, '[{"id": "A", "text": "الأسابيع الأربع بالنسبة للمستويات الأربع الأولى من السلك الابتدائي."}, {"id": "B", "text": "الأسبوع الخامس بالنسبة للمستويات الأربع الأولى من السلك الابتدائي."}, {"id": "C", "text": "الأسبوع الخامس بالنسبة لمستوى السنة الخامسة من السلك الابتدائي."}, {"id": "D", "text": "الأسبوع الخامس بالنسبة لمستوى السنة السادسة من السلك الابتدائي."}]'::jsonb, ARRAY['B']::text[], 'الأسبوع الخامس بالنسبة للمستويات الأربع الأولى. في التوجيهات التربوية 2021 يخصص الأسبوع الخامس من كل وحدة للتقويم والدعم؛ تأكد من التوزيع الخاص بالسنتين الخامسة والسادسة.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان.')
