INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q86', 'exam_primary_2023_didactics_sciences_jan', 86, 'منظور STEM', 'الوضعية 6: «يتأسس تدريس العلوم منذ السنوات الأولى بالمدرسة الابتدائية على اعتبار أهمية التكوين والتأهيل المبكر لتلامذتنا وإعدادهم لمهن المستقبل عبر تشجيعهم على دراسة المواد العلمية والتكنولوجية وفق منظور STEM». (المنهاج الدراسي للتعليم الابتدائي، 2021، ص 348) يُقصد بمنظور STEM:', false, '[{"id": "A", "text": "دمج مواد العلوم ومواد التفتح والتصميم الهندسي والرياضيات."}, {"id": "B", "text": "دمج مواد العلوم وتكنولوجيا الإعلام والاتصال والتصميم الهندسي والرياضيات."}, {"id": "C", "text": "دمج مواد العلوم واللغات وتكنولوجيا الإعلام والاتصال والرياضيات."}, {"id": "D", "text": "دمج مواد العلوم ومواد التفتح وتكنولوجيا الإعلام والاتصال والتصميم الهندسي والرياضيات."}]'::jsonb, ARRAY['B']::text[], 'STEM: Science, Technology, Engineering, Mathematics.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, NULL)
