-- أسئلة امتحان: ديداكتيك النشاط العلمي — Q87
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q87', 'exam_primary_2023_didactics_sciences_jan', 87, 'الرافعات — مرحلة التقصي', 'المجال 3: مبادئ ديدكتيكية عامة لبناء التعلمات. الوضعية 1: خلال حصة للنشاط العلمي خاصة بمستوى السنة السادسة من التعليم الابتدائي حول موضوع الرافعات، ومن أجل التوصل إلى استنتاج قانون الرافعة، وبعد طرح المشكل العلمي، قام المتعلمون(ات) بإنجاز المناولات الثلاث (1) و(2) و(3) بمساعدة المدرس(ة). تمثل الوثيقة ثلاث مناولات على رافعة أفقية مرتكزها في النقطة O: مكعب موضوع في الطرف B، وضغط بالأصبع في الطرف A، مع تغيير المسافة إلى نقطة الارتكاز في كل مناولة. المرحلة التي أنجز فيها المتعلمون(ات) المناولات الممثلة في هذه الوثيقة هي:', false, '[{"id": "A", "text": "صياغة الفرضيات."}, {"id": "B", "text": "إنجاز التقصي."}, {"id": "C", "text": "تقاسم الإنتاجات."}, {"id": "D", "text": "تعميم الاستنتاجات."}]'::jsonb, ARRAY['B']::text[], 'المناولات تنجز في مرحلة التقصي (التحقق من الفرضيات).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, NULL)
