-- أسئلة امتحان: ديداكتيك النشاط العلمي — Q88
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q88', 'exam_primary_2023_didactics_sciences_jan', 88, 'الرافعات — بناء النموذج', 'تتمة الوضعية 1 (انظر وثيقة السؤال 87). حاول المدرس(ة) مساعدة المتعلمين(ات) على بناء النموذج أسفله انطلاقا من نتائج المناولات المنجزة؛ إلا أنه لاحظ وجود صعوبات تعيق بناءهم لهذا النموذج. يمثل النموذج رافعة أفقية مرتكزها في النقطة O، تحمل في أحد طرفيها القرص (ب) وكتلته (2×m) على المسافة (D)، وفي الطرف الآخر القرص (أ) وكتلته (m) على ضعف المسافة (2×D). أصل الصعوبة التي واجهت المتعلمين(ات) في بناء النموذج أعلاه انطلاقا من نتائج المناولات هو:', false, '[{"id": "A", "text": "عدم الضغط بالقرص(أ) في النقطة A المقابلة لموضع المكعب في النقطة B في الطرف الآخر من الرافعة."}, {"id": "B", "text": "الضغط بالأصبع في النقطة A المقابلة لموضع المكعب في النقطة B في الطرف الآخر من الرافعة."}, {"id": "C", "text": "عدم الضغط بالقرص(ب) في النقطة A المقابلة لموضع المكعب في النقطة B في الطرف الآخر من الرافعة."}, {"id": "D", "text": "الضغط بالأصبع في النقطة A المقابلة لموضع القرص (ب) في النقطة B في الطرف الآخر من الرافعة."}]'::jsonb, ARRAY['B']::text[], 'قوة الأصبع غير مقيسة، فلا يمكن ربط النتائج بكتل الأقراص في النموذج. في المناولات استُعمل الضغط بالأصبع (قوة غير مقيسة) بينما يعتمد النموذج على كتل الأقراص، فلا يمكن المقارنة.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان.')
