VALUES ('exam_primary_2023_didactics_sciences_jan_q89', 'exam_primary_2023_didactics_sciences_jan', 89, 'المشروع — تتابع الخطوات', 'اتفق المدرس(ة) مع متعلميه على مشروع إنجاز ميزان، باعتماد المواد المتوفرة بالمحيط المباشر القابلة لإعادة التدوير. التتابع الصحيح لخطوات إنجاز هذا المشروع هو:', false, '[{"id": "A", "text": "تصميم المشروع - اختيار المشروع - تطوير المشروع - إنشاء المشروع."}, {"id": "B", "text": "اختيار المشروع - إنشاء المشروع - تصميم المشروع - تطوير المشروع."}, {"id": "C", "text": "اختيار المشروع - تصميم المشروع - إنشاء المشروع - تطوير المشروع."}, {"id": "D", "text": "تصميم المشروع - إنشاء المشروع - اختيار المشروع - تطوير المشروع."}]'::jsonb, ARRAY['C']::text[], 'اختيار المشروع ثم تصميمه ثم إنشاؤه ثم تطويره.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, NULL)
