-- أسئلة امتحان: ديداكتيك النشاط العلمي — Q90
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q90', 'exam_primary_2023_didactics_sciences_jan', 90, 'الوضعية 2 — نوع النشاط', 'الوضعية 2: خلال نشاط تعليمي تعلمي حول خاصيات المادة، قدم مدرس(ة) نتائج مناولات ممثلة في الجدول أسفله، مطالبا المتعلمين(ات) بتعرف المواد المستعملة خلال هذه المناولات من ضمن: الخشب، الفولاذ، الألمنيوم، الحصى، البلاستيك، النحاس، الفضة. الجدول: المادة 1: تغوص في الماء (نعم)، تشتعل بسهولة (لا)، تنجذب للمغناطيس (نعم). المادة 2: تغوص في الماء (لا)، تشتعل بسهولة (نعم)، تنجذب للمغناطيس (لا). المادة 3: تغوص في الماء (نعم)، تشتعل بسهولة (لا)، تنجذب للمغناطيس (لا). يندرج هذا النشاط ضمن:', false, '[{"id": "A", "text": "أنشطة التطبيق."}, {"id": "B", "text": "أنشطة التفتح."}, {"id": "C", "text": "أنشطة البناء."}, {"id": "D", "text": "أنشطة الامتداد."}]'::jsonb, ARRAY['C']::text[], 'نشاط لبناء معرفة خاصيات المواد. النشاط يبني معرفة جديدة حول خاصيات المواد؛ قد يُعد نشاط تطبيق (A) إذا سبق تقديم هذه الخاصيات.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان. تعارض منشور: mesconcours.ma يقترح A (أنشطة التطبيق)، مع وضع ⚠ على السؤال، ويقول إن C وارد إن اعتُبر استثمار جدول النتائج لحظة بناء لمفهوم «الخاصية المميزة للمادة». الجواب المعتمد هنا هو جواب manasseb (C).')
