VALUES ('exam_primary_2023_didactics_sciences_jan_q92', 'exam_primary_2023_didactics_sciences_jan', 92, 'الوضعية 2 — المهارتان', 'الوضعية 2: خلال نشاط تعليمي تعلمي حول خاصيات المادة، قدم مدرس(ة) نتائج مناولات ممثلة في الجدول أسفله، مطالبا المتعلمين(ات) بتعرف المواد المستعملة خلال هذه المناولات من ضمن: الخشب، الفولاذ، الألمنيوم، الحصى، البلاستيك، النحاس، الفضة. الجدول: المادة 1: تغوص في الماء (نعم)، تشتعل بسهولة (لا)، تنجذب للمغناطيس (نعم). المادة 2: تغوص في الماء (لا)، تشتعل بسهولة (نعم)، تنجذب للمغناطيس (لا). المادة 3: تغوص في الماء (نعم)، تشتعل بسهولة (لا)، تنجذب للمغناطيس (لا). تتمة الوضعية 2 (انظر جدول السؤال 90). المهارتان الأساسيتان اللتان يروم المدرس(ة) تنميتهما لدى المتعلمين(ات) من خلال هذا النشاط هما:', false, '[{"id": "A", "text": "المقارنة والاستنتاج."}, {"id": "B", "text": "الاستنتاج والتركيب."}, {"id": "C", "text": "التذكر والفهم."}, {"id": "D", "text": "القياس والبرهنة."}]'::jsonb, ARRAY['A']::text[], 'مقارنة الخاصيات واستنتاج طبيعة كل مادة.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, NULL)
