-- أسئلة امتحان: ديداكتيك النشاط العلمي — Q93
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q93', 'exam_primary_2023_didactics_sciences_jan', 93, 'الوضعية 3 — الحصيلة المعرفية', 'الوضعية 3: خلال حصة للنشاط العلمي بمستوى السنة الثالثة من التعليم الابتدائي حول محور خصائص الكائنات الحية ووظائفها وتفاعلها مع البيئة، وخلال خطوة التحقق من الفرضية باستثمار الصورتين أسفله، توصل المتعلمون(ات) بمساعدة المدرس(ة) إلى معطيات الجدول أسفله. نظام الأسنان عند العواشب: غياب الأنياب؛ وجود قضيب عظمي؛ قواطع لقبض وقطع العشب؛ أضراس لحك وسحق الغذاء. نظام الأسنان عند اللواحم: قواطع صغيرة ذات دور محدود؛ أنياب قوية لتمزيق لحم الفريسة؛ أضراس منشارية لتقطيع اللحم. يتوصل المتعلم(ة) إلى الحصيلة المعرفية الآتية:', false, '[{"id": "A", "text": "جرد خاصيات بعض الأعضاء الأساسية المحددة للنظام الغذائي عند حيوان لاحم وحيوان عاشب."}, {"id": "B", "text": "تصنيف الحيوانات إلى لاحمة وعاشبة حسب وظائف أعضائها الأساسية للنظام الغذائي."}, {"id": "C", "text": "تحديد الأعضاء الأساسية للنظام الغذائي المشتركة بين الحيوانات اللاحمة والعاشبة."}, {"id": "D", "text": "استنتاج الأعضاء الأساسية للنظام الغذائي العاشب والنظام الغذائي اللاحم."}]'::jsonb, ARRAY['A']::text[], 'الجدول يجرد خاصيات أسنان اللاحم والعاشب. الجدول المنجز يجرد خاصيات أسنان اللاحم والعاشب؛ الاستنتاج والتصنيف (B وD) مرحلة لاحقة.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان.')
