INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q94', 'exam_primary_2023_didactics_sciences_jan', 94, 'الوضعية 3 — النماذج المحاكية', 'الوضعية 3: خلال حصة للنشاط العلمي بمستوى السنة الثالثة من التعليم الابتدائي حول محور خصائص الكائنات الحية ووظائفها وتفاعلها مع البيئة، وخلال خطوة التحقق من الفرضية باستثمار الصورتين أسفله، توصل المتعلمون(ات) بمساعدة المدرس(ة) إلى معطيات الجدول أسفله. نظام الأسنان عند العواشب: غياب الأنياب؛ وجود قضيب عظمي؛ قواطع لقبض وقطع العشب؛ أضراس لحك وسحق الغذاء. نظام الأسنان عند اللواحم: قواطع صغيرة ذات دور محدود؛ أنياب قوية لتمزيق لحم الفريسة؛ أضراس منشارية لتقطيع اللحم. تتمة الوضعية 3 (انظر جدول السؤال 93). شبه المتعلمون(ات) مختلف أنواع الأسنان بأدوات يعرفونها حسب استعمالاتها؛ حيث شبهوا القواطع بإزميل النجار والأضراس بحكاكة الطماطم والأنياب بالسكين والأضراس المنشارية بالمقص. اعتمد المتعلمون(ات) خلال هذا النشاط استعمال نماذج تحاكي:', false, '[{"id": "A", "text": "قوة وبنية مختلف الأسنان."}, {"id": "B", "text": "شكل وبنية مختلف الأسنان."}, {"id": "C", "text": "قوة ووظيفة مختلف الأسنان."}, {"id": "D", "text": "شكل ووظيفة مختلف الأسنان."}]'::jsonb, ARRAY['D']::text[], 'التشبيه بأدوات حسب الاستعمال يحاكي شكل الأسنان ووظيفتها.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, NULL)
