-- أسئلة امتحان: ديداكتيك النشاط العلمي — Q95
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q95', 'exam_primary_2023_didactics_sciences_jan', 95, 'مهارات القرن 21 — التلوث البيئي', 'المجال 4: موارد ديدكتيكية. الوضعية 1: تؤكد التوجيهات التربوية والبرامج الدراسية الخاصة بمادة النشاط العلمي على تنمية مهارات القرن الواحد والعشرين؛ وفي هذا السياق، يهتم تدريس النشاط العلمي بكافة أبعاد التلوث البيئي الذي تم إدماج موضوعاته ابتداء من مستوى السنة الثانية من التعليم الابتدائي. مهارة القرن الواحد والعشرين المرتبطة بموضوع التلوث البيئي هي:', false, '[{"id": "A", "text": "التمكن من المحتوى المعرفي."}, {"id": "B", "text": "التمكن من مهارات التعلم الذاتي والتفكير النقدي."}, {"id": "C", "text": "التمكن من تكنولوجيا المعلومات والاتصالات."}, {"id": "D", "text": "التمكن من المهارات الحياتية."}]'::jsonb, ARRAY['D']::text[], 'التلوث البيئي مرتبط بالمهارات الحياتية (المواطنة والمسؤولية البيئية). التلوث البيئي يرتبط بالمواطنة والمسؤولية، وهي من المهارات الحياتية في تصنيف مهارات القرن 21.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان.')
