-- أسئلة امتحان: ديداكتيك النشاط العلمي — Q96
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q96', 'exam_primary_2023_didactics_sciences_jan', 96, 'مصادر الخطأ — بروسو', 'الوضعية 2: صنف بروسو (Brousseau) مصادر الخطأ في تدريس العلوم إلى مصدر نشوئي يتعلق بتجاوز المستوى النمائي للمتعلم، ومصدر إبستمولوجي يرتبط بصعوبة المفهوم، ومصدر استراتيجي يرتبط بمنهجية التفكير، ومصدر ديدكتيكي يرتبط بالنقل الديدكتيكي وشروطه. خلال إنجاز الوحدة الرابعة في مادة النشاط العلمي لمستوى السنة الخامسة من التعليم الابتدائي حول محور دورات الحياة والتوالد والوراثة عند الكائنات الحية، لم يتم إنجاز التجارب والمناولات المرتبطة بهذه الوحدة. أثناء تقويم المدرس(ة) للكفايات المنهجية لدى المتعلمين(ات)، تبين له/لها أن معظم المتعلمين(ات) يجدون صعوبة في تصور التجارب وإنجازها. مصدر الصعوبة التي اعترضت المتعلمين(ات):', false, '[{"id": "A", "text": "ديدكتيكي."}, {"id": "B", "text": "إبستمولوجي."}, {"id": "C", "text": "استراتيجي."}, {"id": "D", "text": "نشوئي."}]'::jsonb, ARRAY['C']::text[], 'عدم إنجاز التجارب أثر على منهجية التفكير (تصور التجارب): مصدر استراتيجي. عدم إنجاز التجارب أثر على منهجية التفكير (مصدر استراتيجي)؛ قد يُعد ديدكتيكيًا (A) لأن السبب يتعلق بظروف التدريس.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان. تعارض منشور: mesconcours.ma يقترح A (ديدكتيكي)، لأن التجارب لم تُنجز أصلاً فالنقص من شروط التدريس نفسها. الجواب المعتمد هنا هو جواب manasseb (C).')
