-- أسئلة امتحان: ديداكتيك النشاط العلمي — Q97
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q97', 'exam_primary_2023_didactics_sciences_jan', 97, 'النظام الشمسي — الدعامات', 'الوضعية 3: من بين الدعامات الديدكتيكية المعتمدة في تدريس النشاط العلمي بمستوى السنة الخامسة ابتدائي، صور للنظام الشمسي ومجسمات له. تقدم الوثيقتان نموذجين يستعملهما المدرس(ة) في محور «كوكب الأرض في النظام الشمسي»: صورة للنظام الشمسي تظهر فيها الكواكب مصطفة حول الشمس، ومجسم تُثبَّت فيه كريات على قضبان معدنية فوق قاعدة. يطرح استعمال الدعامتين أعلاه مشكلا ديدكتيكيا مشتركا هو:', false, '[{"id": "A", "text": "اصطفاف خطي لمجموع الكواكب والشمس والمسافات بينها."}, {"id": "B", "text": "تمثيل حركية الكواكب نسبة إلى الشمس بارتباط مادي."}, {"id": "C", "text": "ثبات موقع الشمس وعدم احترام الأبعاد والأحجام النسبية للكواكب."}, {"id": "D", "text": "تمثيل الجاذبية بين الكواكب والشمس بارتباط مادي."}]'::jsonb, ARRAY['C']::text[], 'الدعامتان تثبتان الشمس ولا تحترمان النسب بين الأحجام والمسافات.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, NULL)
