-- أسئلة امتحان: ديداكتيك النشاط العلمي — Q99
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note)
VALUES ('exam_primary_2023_didactics_sciences_jan_q99', 'exam_primary_2023_didactics_sciences_jan', 99, 'نموذج SAMR — قرص نيوتن', 'الوضعية 4: حدد الباحث روبن باونتيدورا (Ruben Puentedura) أربع مراحل متتابعة لإدماج تكنولوجيا المعلومات والاتصالات (TIC) في التدريس: استبدال: تستعمل تكنولوجيا المعلومات والاتصالات لتعويض الوسائل التعليمية التناظرية. تعزيز: تستعمل تكنولوجيا المعلومات والاتصالات بطريقة وظيفية لتعزيز عملية بناء التعلمات. تعديل: تستعمل تكنولوجيا المعلومات والاتصالات لإنجاز مهمة المتعلم(ة) في بناء التعلمات بشكل مغاير وإغنائها بفضل الإمكانيات التي تتيحها. إعادة التصميم: تستعمل تكنولوجيا المعلومات والاتصالات لخلق مهام جديدة وأصيلة لا يمكن تحقيقها بدون هذه التكنولوجيا. تفعيلا لمقتضيات المرسوم رقم 2.20.474 الصادر في 15 محرم 1443 الموافق لـ 24 غشت 2021 المتعلق بالتعلم عن بعد، قرر مدرس(ة) إنجاز حصة للنشاط العلمي عن بعد، ولأجل ذلك اعتمد على استثمار موارد رقمية وفرتها مصالح الوزارة عبر موقع Taalimtice.ma، عن طريق التناظر المرئي (vidéoconférence)، بإنجاز تجربة قرص نيوتن قصد التوصل لتركيب الضوء الأبيض من خلال نشاط تفاعلي لمحاكاة التجربة المشار إليها أسفله. تعرض الواجهة قرصا على حامل مع مفتاح تشغيل، ولائحة ألوان مرقمة من 1 إلى 7 (أحمر، برتقالي، أصفر، أخضر، أزرق، نيلي، بنفسجي) يُلوَّن بها القرص بالنقر. المرحلة المناسبة لمستوى إدماج TIC في هذا النشاط حسب الباحث روبن باونتيدورا هي:', false, '[{"id": "A", "text": "استبدال."}, {"id": "B", "text": "تعزيز."}, {"id": "C", "text": "تعديل."}, {"id": "D", "text": "إعادة التصميم."}]'::jsonb, ARRAY['B']::text[], 'المحاكاة تعوض التجربة المادية مع تحسين وظيفي (تفاعل): مرحلة التعزيز. في نموذج SAMR، المحاكاة التي تعوض التجربة مع إضافة التفاعل تقابل مرحلة التعزيز؛ قد تُعد تعديلًا (C).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42530-enseignant-2023/', true, 'إجابة مرجّحة حسب manasseb؛ لا يوجد مفتاح تصحيح رسمي مرفق بالامتحان. تعارض منشور: mesconcours.ma يقترح C (تعديل)، لأن المتعلم ينجز التجربة بنفسه بشكل مغاير (ينقر لوناً بعد لون ويعيد التشغيل ويجرب تركيبات لا يسمح بها قرص مقوى واحد في القسم). الجواب المعتمد هنا هو جواب manasseb (B).')
